text:
.notification-bar {
  padding: 6px 12px;
  margin-block-start: var(--hub-notification-bar-margin-block-start);
  margin-inline: auto;
  inline-size: var(--hub-width);
  text-align: start;
  border: 1px solid;
  border-radius: 3px;

  &[aria-disabled="true"] {
    pointer-events: none;
  }

  &[open=""] #emailFormNotificationToggle {
    span:first-of-type {
      display: none;
    }

    span:last-of-type {
      display: flex;
    }
  }

  #emailFormNotificationToggle {
    span:first-of-type {
      display: flex;
    }

    span:last-of-type {
      display: none;
    }
  }

  .notification-title-container {
    display: flex;
    align-items: center;
    cursor: pointer;

    span {
      font-size: 1.1rem;
      padding-inline-start: 5px;
      margin-inline-start: auto;
    }

    #emailFormNotificationToggle {
      text-decoration: underline;
      white-space: nowrap;
    }

    &:has(#emailFormNotificationToggle:not([hidden])) .notification-title {
      text-align: start;
    }
  }
